unsigned char* LoadPNGFromMemory(const unsigned char* data, size_t size, int* out_width, int* out_height) {
	int channels;
	unsigned char* image_data = stbi_load_from_memory(data, (int)size, out_width, out_height, &channels, 4); // Force RGBA
	if (!image_data) {
		return nullptr;
	}
	return image_data;
}

ID3D11ShaderResourceView* CreateTextureFromImage(
	ID3D11Device* device,
	ID3D11DeviceContext* context,
	const unsigned char* image_data,
	int width,
	int height
) {
	D3D11_TEXTURE2D_DESC texture_desc = {};
	texture_desc.Width = width;
	texture_desc.Height = height;
	texture_desc.MipLevels = 1;
	texture_desc.ArraySize = 1;
	texture_desc.Format = DXGI_FORMAT_R8G8B8A8_UNORM;
	texture_desc.SampleDesc.Count = 1;
	texture_desc.Usage = D3D11_USAGE_DEFAULT;
	texture_desc.BindFlags = D3D11_BIND_SHADER_RESOURCE;

	D3D11_SUBRESOURCE_DATA init_data = {};
	init_data.pSysMem = image_data;
	init_data.SysMemPitch = width * 4; // Row size in bytes (RGBA)

	ID3D11Texture2D* texture = nullptr;
	HRESULT hr = device->CreateTexture2D(&texture_desc, &init_data, &texture);
	if (FAILED(hr)) {
		printf("Failed to create texture: 0x%X\n", hr);
		return nullptr;
	}

	ID3D11ShaderResourceView* srv = nullptr;
	D3D11_SHADER_RESOURCE_VIEW_DESC srv_desc = {};
	srv_desc.Format = texture_desc.Format;
	srv_desc.ViewDimension = D3D11_SRV_DIMENSION_TEXTURE2D;
	srv_desc.Texture2D.MipLevels = 1;

	hr = device->CreateShaderResourceView(texture, &srv_desc, &srv);
	texture->Release(); // Release the texture as the SRV will hold the reference
	if (FAILED(hr)) {
		printf("Failed to create shader resource view: 0x%X\n", hr);
		return nullptr;
	}

	return srv;
}

